from datetime import datetime, timedelta
import re
from typing import Optional, Dict, Any, List


# This functionality is copied from o11y-dashboard-extension
# Link: https://cd.splunkdev.com/observability/splunk-integrations/o11y-dashboard-extension/
#       -/blob/main/src/util/TimeUtils.ts?ref_type=heads
def round_to_hour(dt: datetime) -> datetime:
    """Round datetime to the hour, removing minutes, seconds, microseconds."""
    return dt.replace(minute=0, second=0, microsecond=0)

# NOTE: Function partially generated by Copilot.


def parse_splunk_time(time_str: Optional[str]) -> datetime:
    """
    Parse Splunk time string to datetime object with proper rounding.

    Args:
        time_str: Time string in Splunk format (e.g., '-24h@h', 'now')
    """
    if not time_str:
        return datetime.now()

    if time_str in ('rt', 'now'):
        dt = datetime.now()
        return round_to_hour(dt) if '@h' in time_str else dt

    should_round = '@h' in time_str
    time_str = time_str.replace('rt', '').replace('@h', '')

    if time_str.startswith('-'):
        match = re.match(r'-(\d+)([hdwmy])', time_str)
        if match:
            value, unit = int(match.group(1)), match.group(2)
            now = datetime.now()

            delta = {
                'h': timedelta(hours=value),
                'd': timedelta(days=value),
                'w': timedelta(weeks=value),
                'm': timedelta(minutes=value),
                'y': timedelta(days=value * 365)
            }.get(unit, timedelta(hours=24))

            dt = now - delta
            return round_to_hour(dt) if should_round else dt

    try:
        dt = datetime.fromisoformat(time_str.replace('Z', '+00:00'))
        return round_to_hour(dt) if should_round else dt
    except ValueError:
        dt = datetime.now()
        return round_to_hour(dt) if should_round else dt


def get_time_range(
    earliest: Optional[str] = None,
    latest: Optional[str] = None
) -> Dict[str, Any]:
    """Get start and end times from Splunk time strings."""
    end = parse_splunk_time(latest or 'now')
    start = parse_splunk_time(earliest or '-24h')

    return {
        'start': start,
        'end': end,
        'start_ms': int(start.timestamp()) * 1000,
        'end_ms': int(end.timestamp()) * 1000
    }


# This functionality is copied from o11y-dashboard-extension
# Link: https://cd.splunkdev.com/observability/splunk-integrations/o11y-dashboard-extension/
#       -/blob/main/src/util/GetResolution.ts?ref_type=heads
def get_resolution(
    duration: int,
    point_density: int = 1,
    minimum: int = 0
) -> int:
    """
    Calculate the appropriate resolution for a time series query based on the duration.

    Args:
        duration: Time range duration in milliseconds
        point_density: Density of data points (default: 1)
        minimum: Minimum resolution in milliseconds (default: 0)

    Returns:
        Resolution in milliseconds
    """
    SECOND = 1000
    MINUTE = 60 * SECOND
    HOUR = 60 * MINUTE
    DAY = 24 * HOUR

    allowed_resolutions = [
        SECOND,
        2 * SECOND,
        3 * SECOND,
        4 * SECOND,
        5 * SECOND,
        10 * SECOND,
        20 * SECOND,
        30 * SECOND,
        MINUTE,
        2 * MINUTE,
        3 * MINUTE,
        4 * MINUTE,
        5 * MINUTE,
        15 * MINUTE,
        30 * MINUTE,
        HOUR,
        2 * HOUR,
        3 * HOUR,
        4 * HOUR,
        5 * HOUR,
        6 * HOUR,
        12 * HOUR,
        DAY,
        2 * DAY,
        3 * DAY,
        4 * DAY,
        5 * DAY,
        6 * DAY,
        7 * DAY,
        30 * DAY,
        365 * DAY,
    ]

    DESIRED_NUMBER_OF_POINTS_ON_SCREEN = 60
    rounded_duration = duration - (duration % 1000)
    target_resolution = max(
        rounded_duration / DESIRED_NUMBER_OF_POINTS_ON_SCREEN / point_density,
        minimum
    )
    return find_closest_allowed_value(target_resolution, allowed_resolutions)


def find_closest_allowed_value(
    value: float,
    allowed_values: List[int]
) -> int:
    """
    Find the closest value from a list of allowed values.

    Args:
        value: Target value

    Returns:
        Closest allowed value
    """
    res_idx = next((i for i, res in enumerate(allowed_values) if res > value), -1)
    if res_idx == 0:
        return allowed_values[0]
    if res_idx == -1:
        return allowed_values[-1]
    diff_to_upper = allowed_values[res_idx] - value
    diff_to_lower = value - allowed_values[res_idx - 1]
    return allowed_values[res_idx if diff_to_lower > diff_to_upper else res_idx - 1]
